import{z as o,x as n,o as B,c as s,q as e,j as i,D as E,d as r,s as A,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"关键层对准","description":"","frontmatter":{"title":"关键层对准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/critical-layer-alignment.md","filePath":"litho/critical-layer-alignment.md","lastUpdated":1791063341000}'),d={name:"litho/critical-layer-alignment.md"};function p(h,a,D,C,m,_){const t=n("Mermaid");return B(),s("div",null,[a[2]||(a[2]=e('<h1 id="关键层对准" tabindex="-1">关键层对准 <a class="header-anchor" href="#关键层对准" aria-label="Permalink to &quot;关键层对准&quot;">​</a></h1><div class="epigraph"><p>不是每一层都对到同一张零点；关键层选谁当参考，决定套刻账花在栅对鳍、via 对金属，还是切线对芯轴。</p><footer>—— 对照多层对准策略与 ASML 对准公开论述；[套刻 Overlay](/litho/litho-overlay) 已定义量</footer></div><p><a href="/litho/planarization-dof">上一课</a>把地形写进焦深。缺口是位置：关键层之间要对准到谁，标记在哪一层、经过哪些 CMP 与薄膜。<a href="/litho/alignment-sensors">对准传感器</a> 与 <a href="/litho/alignment-mark-design">标记设计</a> 已讲怎么读；本课钉<strong>策略</strong>：哪一层是关键对、直接对还是间接对。过程控制门的 APC 从下一课开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逻辑栅对鳍、切线对 SAQP 芯轴、via 对金属、BPR 对前层槽，套刻规格不是同一数。对准树若全部指回晶圆零层，中间层的工艺位移会叠成随机游走。直接对准（via 对金属标记）缩短链条，但标记必须在 CMP 后仍可读，衬度与损伤要设计。间接对准省标记面积，把误差预算留给建模。</p><p>缺口是<strong>对准树</strong>，不是再选一次 DBO/IBO。金属–via 协同的 enclosure 规格必须与对准树一致：via 若对错层，覆盖规则是空的。</p><p>为什么「所有层都对回同一张零点」反而更差？每多经过一层中间层，就多吸收一段工艺位移（薄膜应力、热、CMP），套刻误差像接力一样逐段累加。直接对准把链条剪短，代价是标记必须活到最后一步。</p>',7)),(B(),i(l,null,{default:E(()=>[A(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20INDIR%5B%22%E9%97%B4%E6%8E%A5%EF%BC%9A%E5%85%A8%E9%83%A8%E6%8C%87%E5%9B%9E%E9%9B%B6%E5%B1%82%22%5D%0A%20%20%20%20Z%5B%22%E9%9B%B6%E5%B1%82%22%5D%20--%3E%20F%5B%22%E9%B3%8D%EF%BC%88%E4%BD%8D%E7%A7%BB%E4%B8%80%EF%BC%89%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E6%A0%85%EF%BC%88%E4%BD%8D%E7%A7%BB%E4%BA%8C%EF%BC%89%22%5D%0A%20%20%20%20G%20--%3E%20C%5B%22%E5%88%87%E7%BA%BF%EF%BC%88%E4%BD%8D%E7%A7%BB%E4%B8%89%EF%BC%89%22%5D%0A%20%20%20%20C%20--%3E%20V%5B%22via%EF%BC%88%E4%BD%8D%E7%A7%BB%E5%9B%9B%EF%BC%89%22%5D%0A%20%20end%0A%20%20subgraph%20DIR%5B%22%E7%9B%B4%E6%8E%A5%EF%BC%9A%E8%AF%BB%E4%B8%8A%E4%B8%80%E5%B1%82%E6%A0%87%E8%AE%B0%22%5D%0A%20%20%20%20M%5B%22%E9%87%91%E5%B1%9E%E5%B1%82%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20V2%5B%22via%20%E7%9B%B4%E6%8E%A5%E5%AF%B9%E9%87%91%E5%B1%9E%22%5D%0A%20%20end%0A%20%20INDIR%20--%3E%20ACC%5B%22%E5%9B%9B%E6%AE%B5%E4%BD%8D%E7%A7%BB%E6%96%B9%E5%B7%AE%E5%8F%A0%E5%8A%A0%E6%88%90%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%22%5D%0A%20%20DIR%20--%3E%20SML%5B%22%E9%93%BE%E6%9D%A1%E4%B8%80%E6%AE%B5%EF%BC%8C%E9%A2%84%E7%AE%97%E6%9C%80%E7%9F%AD%22%5D%0A%20%20SML%20--%3E%20REQ%5B%22%E8%A6%81%E6%B1%82%EF%BC%9A%E6%A0%87%E8%AE%B0%E7%BB%8F%20CMP%20%E5%90%8E%E4%BB%8D%E5%8F%AF%E8%AF%BB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="关键对不是最多的层" tabindex="-1">关键对不是最多的层 <a class="header-anchor" href="#关键对不是最多的层" aria-label="Permalink to &quot;关键对不是最多的层&quot;">​</a></h3><p>曝光次数最多的层不一定是最严的套刻。切线、接触、via0 往往是关键对；厚金属可能松。策略按 EPE 与电学，不按「光刻课程序号」。SRAM 与逻辑可能不同树，因为阵列标记与边缘标记经历不同 CMP。</p><p><span class="marginnote">术语翻译：「直接对准」是本层曝光时机台直接读上一层的对准标记来定位；「间接对准」是隔着好几层、靠把中间各层的位移量记入模型推算出来。间接省下标记占用的版图面积，代价是把误差预算托付给模型。</span></p><p><span class="marginnote">直觉类比：对准树像传话游戏——消息每经一人转述，就走样一点；转述五个人后的误差是五段走样的叠加。直接对准等于让两人当面说话，链条最短，但要求「说话的人」（标记）一直站在原位不被 CMP 磨花。</span></p><p><span class="marginnote">工艺位移（薄膜应力、热）让标记网格不等于器件网格。高阶校正后课会补；本课要求关键对的标记尽量靠近器件环境。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出层对矩阵：规格、直接/间接、标记层、读数次数。与扫描机：多标记、多色、AH 校正地图。与集成：硬掩模开窗保护标记、CMP dummy 在标记周围。失败模式：错对层、标记损伤、层间滑移。与 <a href="/litho/overlay-budget">套刻预算</a> 数字对齐，本课只决定树的拓扑。</p><p>矩阵要进 MES 与扫描机食谱，避免现场「习惯对到某层」。ASML 对准公开论述把读数策略和校正地图绑在一起；本课把「对谁」放在读数之前，否则地图再密也对错对象。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对准测量的是标记中心；器件套刻是功能图形中心。两者差 = 标记–器件偏置，来自 OPC、刻蚀负荷、CMP。关键层应用产品内标记或专用校准去估这条偏置。树的深度增加方差；直接对准减深度、增工艺对标记存活的要求。</p>',10)),(B(),i(l,null,{default:E(()=>[A(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E9%9B%B6%E5%B1%82%20%2F%20%E9%B3%8D%22%5D%20--%3E%20GATE%5B%22%E6%A0%85%22%5D%0A%20%20GATE%20--%3E%20CUT%5B%22%E5%88%87%E7%BA%BF%22%5D%0A%20%20MET%5B%22%E9%87%91%E5%B1%9E%22%5D%20--%3E%20VIA%5B%22via%20%E7%9B%B4%E6%8E%A5%E5%AF%B9%E5%87%86%22%5D%0A%20%20TREE%5B%22%E5%AF%B9%E5%87%86%E6%A0%91%E9%80%89%E6%8B%A9%22%5D%20--%3E%20OVL%5B%22%E5%85%B3%E9%94%AE%E5%AF%B9%E5%A5%97%E5%88%BB%22%5D%0A%20%20MARK%5B%22%E6%A0%87%E8%AE%B0%E5%AD%98%E6%B4%BB%20%2F%20%E8%A1%AC%E5%BA%A6%22%5D%20--%3E%20TREE%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p>对准树的深度叠加工艺位移。via 直接对金属，是为了缩短链条，不是为了少画标记。错对层会使 enclosure 规则落空。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重写套刻光学。不把某厂对准树当标准。本课结束转印单元；APC 从下一课起是厂级闭环，不再解释等离子体。</p><p>后课默认：关键对有明确对准树，标记环境代表器件。下一课程过程控制用这些读数做 APC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>关键层对准是树的拓扑：直接对缩短链条，要求标记存活。</li><li>规格按 EPE/电学分配，不按曝光次数。</li><li>标记–器件偏置必须进预算。</li><li>出处：ASML 对准公开论述；Levinson 套刻；多层对准策略通称。</li></ul>',6))])}const P=o(d,[["render",p]]);export{u as __pageData,P as default};
